    if (baseIndex > prevBase || sideIndex > prevSide) {
      changes.push({
        side: tag,
        baseStart: prevBase,
        baseEnd: baseIndex,
        lines: side.slice(prevSide, sideIndex),
      })
    }
    prevBase = baseIndex + 1
    prevSide = sideIndex + 1
  }
  if (prevBase < base.length || prevSide < side.length) {
    changes.push({
      side: tag,
      baseStart: prevBase,
      baseEnd: base.length,
      lines: side.slice(prevSide, side.length),
    })
  }
  return changes
