  const regions = []
  let pos = 0
  let index = 0
  while (index < allChanges.length) {
    const first = allChanges[index]
    if (first.baseStart > pos) {
      regions.push({ kind: 'stable', baseStart: pos, baseEnd: first.baseStart })
    }
    const group = [first]
    let regionEnd = first.baseEnd
    index++
    while (index < allChanges.length && allChanges[index].baseStart <= regionEnd) {
      group.push(allChanges[index])
      if (allChanges[index].baseEnd > regionEnd) regionEnd = allChanges[index].baseEnd
      index++
    }
    regions.push({ kind: 'changed', baseStart: first.baseStart, baseEnd: regionEnd, changes: group })
    pos = regionEnd
  }
  if (pos < base.length) {
    regions.push({ kind: 'stable', baseStart: pos, baseEnd: base.length })
