  let pos = region.baseStart
  for (const change of sideChanges) {
    if (change.baseStart > pos) lines.push(...base.slice(pos, change.baseStart))
    lines.push(...change.lines)
    pos = change.baseEnd
  }
  if (pos < region.baseEnd) lines.push(...base.slice(pos, region.baseEnd))
  return lines
